insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_tt4_v1'
from (values
('117.326.c.1.A',3,'A senior technical director uses terms like ''strike,'' ''spike'' and ''hang'' daily when leading a crew. This shows regular use of ___.','["Standard technical theatre vocabulary", "Silence", "Slang", "Vague terms"]'::jsonb,0,'Professionals use precise terms.','original'),
('117.326.c.1.A',3,'''Spiking'' the stage means ___.','["Printing a program", "Marking the floor to show where scenery or furniture belongs", "Cutting a board", "Painting the cyc"]'::jsonb,1,'Spike tape marks positions.','original'),
('117.326.c.1.B',3,'A senior crew head knows the difference between a traveler curtain and a fly drop. This is a working knowledge of ___.','["Ticket tiers", "Concession menus", "Technical stage elements", "Seating charts"]'::jsonb,2,'Technical knowledge covers stage equipment.','original'),
('117.326.c.1.B',3,'A trap room lets scenery and actors ___.','["Hang from the ceiling", "Slide into the lobby", "Disappear from the audience''s seat", "Enter or exit through openings in the stage floor"]'::jsonb,3,'Traps are floor openings.','original'),
('117.326.c.1.C',3,'A senior creates a tech rehearsal plan that lists the order of cues, scene changes and time estimates. She is ___ a theatre system.','["Creating", "Selling", "Burying", "Rejecting"]'::jsonb,0,'Plans organize technical work.','original'),
('117.326.c.1.C',3,'What is a production schedule used for beyond rehearsal dates?','["Only choosing snacks", "Coordinating load-in, tech, dress rehearsals, performances and strike", "Seating the audience", "Writing reviews"]'::jsonb,1,'Schedules plan the whole process.','original'),
('117.326.c.1.D',3,'A senior crew chief models safety by leading a pre-show check of ladders, cables and exits. This is an example of ___.','["Risk taking", "Skipping steps", "Safe practice leadership", "Avoiding duties"]'::jsonb,2,'Leaders model safety.','original'),
('117.326.c.1.D',3,'Which action models safe lifting in the scene shop?','["Lift with the back bent", "Throw the piece", "Lift alone no matter the weight", "Bend the knees, keep the back straight and ask for help with heavy pieces"]'::jsonb,3,'Safe lifting prevents injury.','original'),
('117.326.c.1.E',3,'A senior teaches younger students to break down a script into a technical needs list by scene. This is ___.','["Script analysis for technical theatre", "Casting", "Rehearsal snacks", "Marketing"]'::jsonb,0,'Breakdowns list needs.','original'),
('117.326.c.1.E',3,'A line says ''He lights a cigarette in the dim room.'' Which technical areas are involved?','["Only programs", "Properties, lighting and safety planning", "Only box office", "Only parking"]'::jsonb,1,'Several departments handle this.','original'),
('117.326.c.2.A',3,'A student compares how the technical elements in a farce differ from those in a tragedy. She is ___ elements.','["Ignoring", "Avoiding", "Analyzing", "Burying"]'::jsonb,2,'Analysis compares styles.','original'),
('117.326.c.2.A',3,'A realistic drama usually relies on ___.','["Pure abstraction only", "Random objects", "No design", "Believable settings, motivated lighting and natural sound"]'::jsonb,3,'Realism needs believable elements.','original'),
('117.326.c.2.B',3,'A senior submits an original lighting concept that uses color and angle to show a character''s emotional journey. She is ___ creativity in design.','["Demonstrating", "Dropping", "Hiding", "Avoiding"]'::jsonb,0,'Original ideas show creativity.','original'),
('117.326.c.2.B',3,'Which approach shows creativity in designing a theatrical product?','["Copying a catalog design", "Combining unusual materials to express the play''s theme", "Using no plan", "Ignoring the script"]'::jsonb,1,'Creativity solves problems originally.','original'),
('117.326.c.2.C',3,'A senior serves as the head of the lighting crew and assigns tasks, trains new members and checks the work. She is ___ leadership skills.','["Declining", "Dodging", "Demonstrating", "Ignoring"]'::jsonb,2,'Leaders guide departments.','original'),
('117.326.c.2.C',3,'A strong department head ___.','["Hoards information", "Blames others", "Avoids deadlines", "Communicates clearly, plans ahead and supports the team"]'::jsonb,3,'Leadership requires communication.','original'),
('117.326.c.2.D',3,'A senior leads a short meeting where each crew member shares progress and problems. She is modeling ___.','["Collaboration and leadership", "Confusion", "Delay", "Isolation"]'::jsonb,0,'Meetings build collaboration.','original'),
('117.326.c.2.D',3,'Which action best models collaboration on a production team?','["Skipping meetings", "Listening to each department''s needs and adjusting plans together", "Working in secret", "Rejecting all input"]'::jsonb,1,'Collaboration requires listening.','original'),
('117.326.c.2.E',3,'A senior mentors younger students by showing how she turns a rough sketch into a final design and invites their ideas. She is modeling ___.','["Restriction", "Mockery", "Creativity and personal expression", "Conformity"]'::jsonb,2,'Mentors model creative process.','original'),
('117.326.c.2.E',3,'A designer models creative personal expression by ___.','["Rejecting the script", "Copying exactly", "Avoiding decisions", "Making choices that reflect her own point of view while serving the play"]'::jsonb,3,'Personal voice and purpose.','original'),
('117.326.c.2.F',3,'A senior stage manager shares a clear promptbook and a costume plot with the director and designers so everyone has the same information. She is modeling ___.','["Communication between directors and designers", "Competition", "Delay", "Secrecy"]'::jsonb,0,'Documents share information.','original'),
('117.326.c.2.F',3,'What is the purpose of a rehearsal report?','["To collect tickets", "To tell designers and crew what happened and what is needed", "To list audience members", "To advertise the show"]'::jsonb,1,'Reports communicate needs.','original'),
('117.326.c.3.A',3,'A senior models safe use of a nail gun by wearing eye protection, keeping fingers clear and ___.','["Working alone at night", "Pulling the trigger to test", "Never pointing it at anyone", "Removing the safety"]'::jsonb,2,'Safe tool habits.','original'),
('117.326.c.3.A',3,'Properly storing paint and solvents includes ___.','["Storing next to heaters", "Pouring them down any drain", "Leaving them open", "Sealing containers and keeping them in a ventilated cabinet"]'::jsonb,3,'Proper storage prevents fires.','original'),
('117.326.c.3.B',3,'A senior supervising a scenery build checks that platforms are braced and rated for the weight of the actors. She is supervising ___.','["Safe construction", "Unsafe shortcuts", "Decorating only", "Cleaning only"]'::jsonb,0,'Supervisors verify safety.','original'),
('117.326.c.3.B',3,'Why must a platform be tested before actors use it?','["To hide the screws", "To make sure it can hold the weight safely", "To change its color", "To make it louder"]'::jsonb,1,'Testing prevents collapse.','original'),
('117.326.c.3.C',3,'A senior supervising costume construction ensures that irons are unplugged when not in use and that scissors are stored safely. She is supervising ___.','["Unplanned storage", "Risky shortcuts", "Safe use of costume and makeup techniques", "Casual play"]'::jsonb,2,'Supervisors enforce safety.','original'),
('117.326.c.3.C',3,'Which is a safe makeup practice for a supervisor to enforce?','["Use old eyeshadow", "Share lip products", "Skip cleaning", "Use individual applicators and disinfect shared tools"]'::jsonb,3,'Hygiene prevents infection.','original'),
('117.326.c.3.D',3,'A senior supervising a lighting hang requires that all instruments have safety cables and that ladders are footed by a partner. She is supervising ___.','["Safe use of lighting equipment", "Careless hanging", "Unsecured rigging", "Free climbing"]'::jsonb,0,'Safety gear protects people below.','original'),
('117.326.c.3.D',3,'A circuit is overloaded when the total wattage of lights ___.','["Is zero", "Exceeds the circuit''s rated capacity", "Is below the rating", "Matches the color"]'::jsonb,1,'Overloads cause breakers to trip or fires.','original'),
('117.326.c.3.E',3,'A senior supervising sound checks cables for damage and keeps the volume at a safe level. She is supervising ___.','["Ignoring wear", "Loose cables", "Safe use of sound equipment", "Random noise"]'::jsonb,2,'Safe sound practice protects people and gear.','original'),
('117.326.c.3.E',3,'A frayed audio cable should be ___.','["Plugged in carefully", "Left on the floor", "Taped and used", "Removed from use and repaired or replaced"]'::jsonb,3,'Damaged cables are unsafe.','original'),
('117.326.c.3.F',3,'A senior demonstrates management by organizing the house staff, directing ushers and coordinating with the stage manager before the doors open. She is showing skill in ___.','["House management", "Welding", "Surveying", "Cooking"]'::jsonb,0,'House managers coordinate front-of-house.','original'),
('117.326.c.3.F',3,'Which is a key duty of a stage manager during a performance?','["Printing the poster", "Calling cues and keeping the show running safely", "Selling tickets", "Painting the lobby"]'::jsonb,1,'Stage managers call the show.','original'),
('117.326.c.4.A',3,'A senior argues that using accurate period fabrics and silhouettes helps the audience believe the world of a play. She is ___ historical accuracy.','["Rejecting", "Mocking", "Defending", "Ignoring"]'::jsonb,2,'Defending means supporting with reasons.','original'),
('117.326.c.4.A',3,'Why might a designer defend cultural accuracy in costumes?','["It lowers the budget", "It avoids research", "It confuses the audience", "It respects the culture and strengthens the story"]'::jsonb,3,'Accuracy builds respect.','original'),
('117.326.c.4.B',3,'A senior explains that film''s close-ups and editing influence how audiences expect to see live theatre. She is ___ the impact of media.','["Articulating", "Hiding", "Burying", "Denying"]'::jsonb,0,'Articulate means to express clearly.','original'),
('117.326.c.4.B',3,'Which statement shows the impact of television and electronic media on contemporary theatre?','["Theatre banned technology", "Many productions use projections, microphones and video", "Actors stopped performing live", "Theatre never changed"]'::jsonb,1,'Media blends into live theatre.','original'),
('117.326.c.4.C',3,'A senior presents on how Greek amphitheaters, Asian mask traditions and Elizabethan stages shaped later theatre design. She is articulating the impact of ___.','["Cooking", "Sports", "Cultural heritages of world theatre", "Cartoons"]'::jsonb,2,'World traditions influenced design.','original'),
('117.326.c.4.C',3,'Which key figure is a major playwright of Elizabethan England?','["Anton Chekhov", "Henrik Ibsen", "Sophocles", "William Shakespeare"]'::jsonb,3,'Shakespeare is the key Elizabethan playwright.','original'),
('117.326.c.4.D',3,'A senior explains that playwrights such as August Wilson, Lorraine Hansberry and Luis Valdez shaped American drama through cultural stories. She is articulating the impact of ___.','["The multicultural heritage of US theatre", "Fiction only", "A single tradition", "Foreign theatre only"]'::jsonb,0,'U.S. theatre is multicultural.','original'),
('117.326.c.4.D',3,'Which pair shows the diversity of American theatre?','["Only opera", "Chicano theatre and African American theatre", "Only Greek theatre", "Only silent film"]'::jsonb,1,'They represent distinct traditions.','original'),
('117.326.c.4.E',3,'A senior predicts that augmented reality and motion-tracking lighting could soon change live performance. She is ___ future innovations.','["Avoiding", "Remembering", "Predicting", "Denying"]'::jsonb,2,'Predicting means forecasting.','original'),
('117.326.c.4.E',3,'Which technology might designers of the future use to create flexible sets?','["Only paper", "Only chalk", "Only candles", "Projection mapping and automated scenery"]'::jsonb,3,'Automation and projection are emerging tools.','original'),
('117.326.c.5.A',3,'A senior updates a resume and portfolio and uses them to apply to a college program. She is ___ them.','["Using", "Hiding", "Losing", "Burying"]'::jsonb,0,'Using means applying in a real setting.','original'),
('117.326.c.5.A',3,'Which item in a technical theatre portfolio strengthens a college application?','["Blank pages", "Labeled plots, drawings and photos of finished builds", "A menu", "One unlabeled photo"]'::jsonb,1,'Evidence of skill helps.','original'),
('117.326.c.5.B',3,'A senior crew head arrives early, dresses in dark clothing and stays quiet backstage to model professionalism. This is ___.','["Casual chatting", "Carelessness", "Appropriate technical staff behavior", "Disruptive behavior"]'::jsonb,2,'Professional conduct sets examples.','original'),
('117.326.c.5.B',3,'During a performance, a technician should ___.','["Wander the house", "Use a phone", "Watch videos", "Stay focused on cues and communicate only through the headset when needed"]'::jsonb,3,'Focus is vital.','original'),
('117.326.c.5.C',3,'A senior writes an argument that lighting, sound and scenery are an art form that shapes how audiences feel. She is ___ technical design.','["Defending", "Ridiculing", "Dismissing", "Ignoring"]'::jsonb,0,'Defend means to argue support.','original'),
('117.326.c.5.C',3,'Self-evaluation as a creative being includes ___.','["Avoiding reflection", "Reflecting on risks taken, lessons learned and goals for growth", "Blaming others", "Ignoring feedback"]'::jsonb,1,'Reflection builds growth.','original'),
('117.326.c.5.D',3,'After reviewing a model, a senior says: ''The platform layout supports the blocking well; consider a lighter material to speed scene shifts.'' This is ___.','["Spam", "An insult", "Constructive criticism", "Rumor"]'::jsonb,2,'Praise plus a suggestion.','original'),
('117.326.c.5.D',3,'When receiving peer feedback on a design, a professional ___.','["Leaves", "Ignores", "Argues", "Listens, asks clarifying questions and decides what to use"]'::jsonb,3,'Open receptivity improves work.','original'),
('117.326.c.5.E',3,'A review observes that the rotating scenery supported the shifting time frame and the lighting softened each transition. This is ___.','["Precise and specific evaluation", "Off topic", "Silent", "Vague"]'::jsonb,0,'Detailed observations.','original'),
('117.326.c.5.E',3,'Which sentence is a precise evaluation of a live production?','["It was long", "The sharp white side light isolated the speaker and heightened her isolation", "Good job", "It was fine"]'::jsonb,1,'Precise language names effect.','original'),
('117.326.c.5.F',3,'A senior compares how sound is layered in a film with how it is used in a live show, citing specific examples. She is ___ media.','["Selling", "Hiding", "Evaluating", "Avoiding"]'::jsonb,2,'Evaluation uses specifics.','original'),
('117.326.c.5.F',3,'Which comment about a television show''s set design is precise?','["I liked it", "Looked okay", "It had walls", "The cramped apartment set matched the character''s sense of confinement"]'::jsonb,3,'Precise observations tie design to meaning.','original'),
('117.326.c.5.G',3,'A senior describes how a technical director, lighting programmer and scenic carpenter work in theatre, film and theme parks. She is articulating ___.','["Career opportunities", "Hobbies only", "Fantasies", "Rumors"]'::jsonb,0,'Technical skills transfer to industries.','original'),
('117.326.c.5.G',3,'Which is an avocational way to stay involved in technical theatre after school?','["Selling cars", "Volunteering at a community theatre", "Quitting theatre", "Ignoring theatre"]'::jsonb,1,'Avocational means for enjoyment.','original'),
('117.326.c.5.H',3,'A senior says that crew leadership taught her project planning and communication that will help in college and business. She is ___ theatre skills to careers.','["Dropping", "Hiding", "Connecting", "Ending"]'::jsonb,2,'Skills transfer.','original'),
('117.326.c.5.H',3,'Which technical theatre skill helps most in many careers?','["Ignoring plans", "Skipping safety", "Avoiding teamwork", "Problem solving under deadlines"]'::jsonb,3,'Deadline-based problem solving transfers.','original'),
('117.326.c.5.I',3,'A senior uses a slide presentation with photos, drawings and short captions to share her design process with a panel. She is using ___ to present findings.','["Technology", "A paintbrush only", "A saw", "A hammer"]'::jsonb,0,'Slides share information.','original'),
('117.326.c.5.I',3,'A coherent technical presentation includes ___.','["Random slides", "A clear order, labeled visuals and short explanations", "No sequence", "Unlabeled images"]'::jsonb,1,'Clarity supports understanding.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
